endpoint.curlExample:
curl --location --request PUT 'https://api.onlinesales.ai/marketing/v1/advertiser/<advertiser_id>/sponsored_products/campaigns/<campaign_id>/category_bid_setting' \
--header 'x-retailer-id: <ADD RETAILER-ID HERE>' \
--header 'x-token: <ADD YOUR AUTH TOKEN HERE>' \
--header 'Content-Type: application/json' \
--data '{
    "category_bid_setting": {
        "mode": "MANUAL",
        "category_bids": [
            {
                "category_value": "Frozen > Frozen Desserts > Frozen Yogurt",
                "bid_value": 14,
                "is_active": true
            }
        ]
    }
}'
